/* ---------------- food database ----------------
   USDA SR Legacy (public domain) and CoFID / McCance & Widdowson's (Open
   Government Licence), reduced to the five numbers this app logs, per 100 g.

   The curated LOCAL_FOODS table above stays, because it is the only source of
   per-item weights — an egg is 50 g, a slice of bread 40 g, a pint 568 ml — and
   the datasets only ever describe 100 g. So the two are used for different
   halves of the answer:

     what it is   -> the curated table when it knows the food, the database
                     otherwise. Curated is hand-tuned and encodes the form
                     people log — rice and pasta cooked, mince at 5%, a whole
                     egg — where both datasets lead with raw weights. Letting
                     the database override turned 250 g of rice into 878 kcal.
     how much     -> the curated per-item weight when a count was given,
                     otherwise the grams stated.

   The model is now the fallback, not the path: an ordinary day of food costs
   nothing to log. */

/* Both datasets are American-spelled or use the formal name; people type
   neither. The query is rewritten before matching, never the table. */
const FOOD_SYNONYMS = {
  // spellings CoFID does not use
  yoghurt: 'yogurt', yog: 'yogurt', hummus: 'houmous',
  // everyday shorthand
  mayo: 'mayonnaise', veg: 'vegetables', spuds: 'potatoes', brew: 'tea',
  jacket: 'baked', tinned: 'canned', fizzy: 'carbonated',
};

/* Words that describe amount or freshness rather than the food. Dropping them
   means "200g raw chicken" and "chicken" reach the same row. */
const FOOD_STOP = new Set([
  'a', 'an', 'the', 'of', 'with', 'some', 'my', 'and', 'plus', 'about', 'approx',
  'g', 'gram', 'grams', 'gr', 'kg', 'ml', 'l', 'litre', 'oz', 'lb', 'lbs', 'x',
  'raw', 'fresh', 'slice', 'slices', 'piece', 'pieces', 'serving', 'servings',
  'one', 'two', 'three', 'four', 'five', 'six', 'half', 'couple', 'few',
]);

function foodTokens(s) {
  return String(s || '').toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/)
    .filter(w => w && !/^\d/.test(w) && !FOOD_STOP.has(w))
    .map(w => FOOD_SYNONYMS[w] || w);
}

/* A short query with no qualifier means the plain version of the food. The
   datasets lead with flavoured and processed variants as often as not, so
   nudge toward the ordinary one and away from the ones nobody meant. */
const FOOD_PLAIN = /\b(plain|natural|unsweetened|whole|boiled|grilled|unfortified)\b/;
const FOOD_FANCY = /\b(fruit|flavou?red|chocolate|strawberry|barbecue|sweetened|toasted|fried|battered|dried|powder|infant|baby)\b/;


